import * as THREE from 'three';

const DEG = Math.PI / 180;
const JITTER_DEG = 5; // max seeded jitter (degrees) applied to the pitch angle

/**
 * Deterministic PRNG (mulberry32). Returns a function producing
 * uniform floats in [0, 1) from an integer seed.
 */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// One shared unit cylinder, base at origin, tip at y = 1.
// Each branch's mesh is scaled to the branch's current length/radius.
const UNIT_CYLINDER = new THREE.CylinderGeometry(1, 1, 1, 8);
UNIT_CYLINDER.translate(0, 0.5, 0);

const SHARED_MATERIAL = new THREE.MeshStandardMaterial({ color: 0x8a5a2b });

/**
 * Grow a recursive fractal tree out of nested THREE.Group nodes.
 *
 * Every branch is a Group containing:
 *  - a cylinder mesh of the branch's current length, base at the group origin,
 *    tip at local y = length
 *  - `branchFactor` child Groups attached at the tip, each pitched `spreadDeg`
 *    away from the parent axis (plus seeded jitter of up to 5 degrees) and spun
 *    evenly around the parent axis
 *  - recursion stops once `depth` levels have been built
 *
 * @param {object} opts
 * @param {number} opts.depth          number of levels below (and including) the trunk
 * @param {number} [opts.branchFactor=2]
 * @param {number} [opts.length=4]     trunk length
 * @param {number} [opts.ratio=0.7]    child length = parent length * ratio
 * @param {number} [opts.spreadDeg=35] pitch angle between parent and child axes
 * @param {number} [opts.seed=1]       integer seed for the jitter RNG
 * @returns {THREE.Group} root group of the tree
 */
export function growTree({
  depth,
  branchFactor = 2,
  length = 4,
  ratio = 0.7,
  spreadDeg = 35,
  seed = 1,
}) {
  const rng = mulberry32(seed);
  return buildBranch(depth, length);

  function buildBranch(levelsLeft, len) {
    const group = new THREE.Group();
    group.userData.branch = true;
    group.userData.length = len;

    const mesh = new THREE.Mesh(UNIT_CYLINDER, SHARED_MATERIAL);
    mesh.scale.set(len * 0.06, len, len * 0.06); // thin relative to length
    mesh.userData.isBranchMesh = true;
    group.add(mesh);

    if (levelsLeft > 0) {
      for (let i = 0; i < branchFactor; i++) {
        const child = buildBranch(levelsLeft - 1, len * ratio);

        // Attach at the parent tip.
        child.position.set(0, len, 0);

        // Spin evenly around the parent axis first, then pitch away from it.
        const spin = (i / branchFactor) * Math.PI * 2;
        const jitter = (rng() - 0.5) * 2 * JITTER_DEG * DEG;
        const pitch = spreadDeg * DEG + jitter;
        // Default 'XYZ' euler order => v' = Rx(pitch) * Ry(spin) * v,
        // i.e. spin about the parent axis, then tilt by the pitch angle.
        child.rotation.set(pitch, spin, 0);

        group.add(child);
      }
    }
    return group;
  }
}

/** Recursively count all branch groups in the tree (root included). */
export function countBranches(tree) {
  let count = 1;
  for (const child of tree.children) {
    if (child.userData && child.userData.branch) {
      count += countBranches(child);
    }
  }
  return count;
}

/** Height of the tree as the y-extent of its world-space bounding box. */
export function treeHeight(tree) {
  tree.updateWorldMatrix(true, true);
  const box = new THREE.Box3().setFromObject(tree);
  return box.max.y - box.min.y;
}

/**
 * World-space positions of every branch tip (local point (0, length, 0)
 * of each branch group). Useful for determinism checks.
 */
export function collectTipPositions(tree) {
  tree.updateWorldMatrix(true, true);
  const tips = [];
  const tmp = new THREE.Vector3();
  (function walk(node) {
    if (node.userData && node.userData.branch) {
      tmp.set(0, node.userData.length, 0).applyMatrix4(node.matrixWorld);
      tips.push(tmp.clone());
    }
    for (const child of node.children) walk(child);
  })(tree);
  return tips;
}

