import { describe, it, expect } from 'vitest';
import {
  growTree,
  countBranches,
  treeHeight,
  collectTipPositions,
} from '../src/tree.js';

describe('countBranches', () => {
  it('counts 2^5 - 1 = 31 branches for depth 4, branchFactor 2', () => {
    const tree = growTree({ depth: 4, branchFactor: 2 });
    expect(countBranches(tree)).toBe(31);
  });

  it('counts (3^4 - 1)/2 = 40 branches for depth 3, branchFactor 3', () => {
    const tree = growTree({ depth: 3, branchFactor: 3 });
    expect(countBranches(tree)).toBe(40);
  });
});

describe('treeHeight', () => {
  const length = 4;
  const ratio = 0.7;

  it('is bounded by the geometric series sum and the trunk length', () => {
    const tree = growTree({ depth: 4 });
    const h = treeHeight(tree);

    const seriesSum =
      length * (1 + ratio + ratio ** 2 + ratio ** 3 + ratio ** 4);

    expect(h).toBeGreaterThan(length);
    expect(h).toBeLessThan(seriesSum);
  });
});

describe('seeded determinism', () => {
  const serializeTips = (tips) =>
    tips.map((p) => `${p.x},${p.y},${p.z}`).join(';');

  it('reproduces identical world tip positions for the same seed', () => {
    const a = collectTipPositions(growTree({ depth: 4, seed: 42 }));
    const b = collectTipPositions(growTree({ depth: 4, seed: 42 }));

    expect(a.length).toBe(b.length);
    expect(serializeTips(a)).toBe(serializeTips(b));
  });

  it('produces different world tip positions for different seeds', () => {
    const a = collectTipPositions(growTree({ depth: 4, seed: 42 }));
    const b = collectTipPositions(growTree({ depth: 4, seed: 1337 }));

    expect(a.length).toBe(b.length);
    expect(serializeTips(a)).not.toBe(serializeTips(b));
  });
});

